// Build the Daily OEE Report email from the sheet rows (v2: with reasons + action list)
const rows = $input.all().map(i => i.json);

// 1. Empty-sheet check: no machine rows -> stop (no blank email)
const valid = rows.filter(r => r.Machine && String(r.Machine).trim() !== "");
if (valid.length === 0) {
  return [];
}

// Helpers
const num = v => Number(v) || 0;
const pct = v => (v * 100).toFixed(1) + "%";
const txt = v => (v === undefined || v === null || String(v).trim() === "" || String(v).trim() === "-") ? "" : String(v).trim();

let tPlanned = 0, tRun = 0, tIdeal = 0, tTotal = 0, tGood = 0;
const lines = [];
const actions = [];

// 2. OEE for each machine
for (const r of valid) {
  const planned = num(r.Planned_Time_Min);
  const down    = num(r.Downtime_Min);
  const cycle   = num(r.Ideal_Cycle_Time_Sec);
  const total   = num(r.Total_Count);
  const good    = num(r.Good_Count);
  const downWhy = txt(r.Downtime_Reason);
  const rejWhy  = txt(r.Reject_Reason);

  const run = Math.max(planned - down, 0);
  const A = planned > 0 ? run / planned : 0;
  const P = run > 0 ? (cycle * total) / (run * 60) : 0;
  const Q = total > 0 ? good / total : 0;
  const oee = A * P * Q;

  tPlanned += planned; tRun += run; tIdeal += cycle * total;
  tTotal += total; tGood += good;

  const flag = oee >= 0.85 ? "✅" : oee >= 0.6 ? "⚠️" : "🔴";
  let line = `${flag} ${r.Machine} (${r.Shift}): OEE ${pct(oee)} | A ${pct(A)} | P ${pct(P)} | Q ${pct(Q)} | Good ${good}/${total} | Downtime ${down} min`;
  if (downWhy) line += ` (${downWhy})`;
  if (rejWhy && total - good > 0) line += ` | Rejects ${total - good} (${rejWhy})`;
  lines.push(line);

  // 3. Action list: machines below 85%, with their biggest loss
  if (oee < 0.85) {
    const losses = [
      { name: "Availability (stoppage)", v: A, why: downWhy },
      { name: "Performance (slow running)", v: P, why: "" },
      { name: "Quality (rejects)", v: Q, why: rejWhy }
    ].sort((a, b) => a.v - b.v);
    const main = losses[0];
    actions.push(`- ${r.Machine}: main loss = ${main.name} ${pct(main.v)}` + (main.why ? ` → reason: ${main.why}` : ""));
  }
}

// 4. Plant OEE
const pA = tPlanned > 0 ? tRun / tPlanned : 0;
const pP = tRun > 0 ? tIdeal / (tRun * 60) : 0;
const pQ = tTotal > 0 ? tGood / tTotal : 0;
const pOEE = pA * pP * pQ;

// 5. Build the email
const date = valid[0].Date;
const subject = `Daily OEE Report – ${date} – Plant OEE ${pct(pOEE)}`;
const body = [
  "Hi Sir,",
  "",
  `Here is the OEE summary for ${date} (${valid.length} machines):`,
  "",
  ...lines,
  "",
  `PLANT OEE: ${pct(pOEE)}  (Availability ${pct(pA)} x Performance ${pct(pP)} x Quality ${pct(pQ)})`,
  `Total good parts: ${tGood} / ${tTotal}`,
  "",
  "ACTION NEEDED (machines below 85%):",
  ...(actions.length ? actions : ["- None. All machines are world class today."]),
  "",
  "Legend: ✅ 85% and above (world class) | ⚠️ 60-85% | 🔴 below 60%",
  "",
  "Regards,",
  "Production Automation Bot (n8n)"
].join("\n");

return [{ json: { subject, body, machines: valid.length, plant_oee: pct(pOEE) } }];
